"""Baseline for existing CareerLens business databases (immutable migration)."""

TABLES = ['\nCREATE TABLE IF NOT EXISTS api_keys (\n\tprovider VARCHAR NOT NULL, \n\tciphertext TEXT NOT NULL, \n\tupdated_at VARCHAR NOT NULL, \n\tPRIMARY KEY (provider)\n)\n\n', '\nCREATE TABLE IF NOT EXISTS applications (\n\tapplication_id VARCHAR NOT NULL, \n\tjob_id VARCHAR NOT NULL, \n\tresume_id VARCHAR NOT NULL, \n\tmaster_resume_id VARCHAR, \n\tstatus VARCHAR NOT NULL, \n\tcompany VARCHAR, \n\trole VARCHAR, \n\tapplied_at VARCHAR, \n\tnotes TEXT, \n\tposition INTEGER NOT NULL, \n\tcreated_at VARCHAR NOT NULL, \n\tupdated_at VARCHAR NOT NULL, \n\tPRIMARY KEY (application_id), \n\tCONSTRAINT uq_application_job_resume UNIQUE (job_id, resume_id)\n)\n\n', '\nCREATE TABLE IF NOT EXISTS improvements (\n\trequest_id VARCHAR NOT NULL, \n\toriginal_resume_id VARCHAR NOT NULL, \n\ttailored_resume_id VARCHAR NOT NULL, \n\tjob_id VARCHAR NOT NULL, \n\timprovements JSON NOT NULL, \n\tcreated_at VARCHAR NOT NULL, \n\tPRIMARY KEY (request_id)\n)\n\n', '\nCREATE TABLE IF NOT EXISTS jobs (\n\tjob_id VARCHAR NOT NULL, \n\tcontent TEXT NOT NULL, \n\tresume_id VARCHAR, \n\tcreated_at VARCHAR NOT NULL, \n\tmetadata_json JSON NOT NULL, \n\tPRIMARY KEY (job_id)\n)\n\n', '\nCREATE TABLE IF NOT EXISTS resumes (\n\tresume_id VARCHAR NOT NULL, \n\tcontent TEXT NOT NULL, \n\tcontent_type VARCHAR NOT NULL, \n\tfilename VARCHAR, \n\tis_master BOOLEAN NOT NULL, \n\tparent_id VARCHAR, \n\tprocessed_data JSON, \n\tprocessing_status VARCHAR NOT NULL, \n\tprocessing_token VARCHAR, \n\tcover_letter TEXT, \n\toutreach_message TEXT, \n\tinterview_prep TEXT, \n\ttitle VARCHAR, \n\ttemplate_settings JSON, \n\toriginal_markdown TEXT, \n\tcreated_at VARCHAR NOT NULL, \n\tupdated_at VARCHAR NOT NULL, \n\tPRIMARY KEY (resume_id)\n)\n\n', '\nCREATE TABLE IF NOT EXISTS tailoring_previews (\n\timprovements JSON, \n\tpreview_id VARCHAR NOT NULL, \n\tsource_id VARCHAR NOT NULL, \n\tjob_id VARCHAR NOT NULL, \n\tpayload_hash VARCHAR NOT NULL, \n\tsource_hash VARCHAR NOT NULL, \n\tjob_hash VARCHAR NOT NULL, \n\tcreated_at VARCHAR NOT NULL, \n\texpires_at VARCHAR NOT NULL, \n\tresult_resume_id VARCHAR, \n\tclaim_token VARCHAR, \n\tclaim_expires_at VARCHAR, \n\tresponse_data JSON, \n\tPRIMARY KEY (preview_id)\n)\n\n', '\nCREATE TABLE IF NOT EXISTS resume_snapshots (\n\tid VARCHAR NOT NULL, \n\tresume_id VARCHAR NOT NULL, \n\tcontent_hash VARCHAR NOT NULL, \n\tdata JSON NOT NULL, \n\tevidence JSON NOT NULL, \n\tcreated_at VARCHAR NOT NULL, \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(resume_id) REFERENCES resumes (resume_id) ON DELETE CASCADE\n)\n\n', '\nCREATE TABLE IF NOT EXISTS match_records (\n\tid VARCHAR NOT NULL, \n\tsnapshot_id VARCHAR NOT NULL, \n\tjob_id VARCHAR NOT NULL, \n\tjob_snapshot JSON NOT NULL, \n\tjob_hash VARCHAR NOT NULL, \n\tdetails JSON NOT NULL, \n\tconditions JSON NOT NULL, \n\tscore FLOAT, \n\trule_version VARCHAR NOT NULL, \n\tcreated_at VARCHAR NOT NULL, \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(snapshot_id) REFERENCES resume_snapshots (id) ON DELETE CASCADE, \n\tFOREIGN KEY(job_id) REFERENCES jobs (job_id) ON DELETE CASCADE\n)\n\n', '\nCREATE TABLE IF NOT EXISTS rewrite_records (\n\tid VARCHAR NOT NULL, \n\tmatch_id VARCHAR NOT NULL, \n\tsection_id VARCHAR NOT NULL, \n\tfacts JSON NOT NULL, \n\tpayload JSON NOT NULL, \n\tstatus VARCHAR NOT NULL, \n\tresult_resume_id VARCHAR, \n\tcreated_at VARCHAR NOT NULL, \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(match_id) REFERENCES match_records (id) ON DELETE CASCADE, \n\tFOREIGN KEY(result_resume_id) REFERENCES resumes (resume_id) ON DELETE SET NULL\n)\n\n']

INDEXES = [('CREATE INDEX IF NOT EXISTS ix_applications_job_id ON applications (job_id)', 'applications', ['job_id']), ('CREATE INDEX IF NOT EXISTS ix_applications_resume_id ON applications (resume_id)', 'applications', ['resume_id']), ('CREATE INDEX IF NOT EXISTS ix_applications_status ON applications (status)', 'applications', ['status']), ('CREATE INDEX IF NOT EXISTS ix_improvements_tailored_resume_id ON improvements (tailored_resume_id)', 'improvements', ['tailored_resume_id']), ('CREATE UNIQUE INDEX IF NOT EXISTS ux_resumes_single_master ON resumes (is_master) WHERE is_master = 1', 'resumes', ['is_master']), ('CREATE INDEX IF NOT EXISTS ix_tailoring_previews_job_id ON tailoring_previews (job_id)', 'tailoring_previews', ['job_id']), ('CREATE INDEX IF NOT EXISTS ix_preview_compatibility ON tailoring_previews (source_id, job_id, payload_hash, created_at)', 'tailoring_previews', ['source_id', 'job_id', 'payload_hash', 'created_at']), ('CREATE INDEX IF NOT EXISTS ix_tailoring_previews_expires_at ON tailoring_previews (expires_at)', 'tailoring_previews', ['expires_at']), ('CREATE INDEX IF NOT EXISTS ix_tailoring_previews_source_id ON tailoring_previews (source_id)', 'tailoring_previews', ['source_id']), ('CREATE INDEX IF NOT EXISTS ix_tailoring_previews_result_resume_id ON tailoring_previews (result_resume_id)', 'tailoring_previews', ['result_resume_id']), ('CREATE INDEX IF NOT EXISTS ix_resume_snapshots_resume_id ON resume_snapshots (resume_id)', 'resume_snapshots', ['resume_id']), ('CREATE INDEX IF NOT EXISTS ix_match_records_job_id ON match_records (job_id)', 'match_records', ['job_id']), ('CREATE INDEX IF NOT EXISTS ix_match_records_snapshot_id ON match_records (snapshot_id)', 'match_records', ['snapshot_id']), ('CREATE INDEX IF NOT EXISTS ix_rewrite_records_match_id ON rewrite_records (match_id)', 'rewrite_records', ['match_id'])]


def upgrade(connection):
    for statement in TABLES:
        connection.execute(statement)
    # Previously shipped additive changes, retained for older local databases.
    for table, column, definition in (
        ("resumes", "interview_prep", "TEXT"),
        ("resumes", "processing_token", "TEXT"),
        ("resumes", "template_settings", "JSON"),
        ("tailoring_previews", "improvements", "JSON"),
    ):
        names = {row[1] for row in connection.execute(f"PRAGMA table_info({table})")}
        if column not in names:
            connection.execute(f"ALTER TABLE {table} ADD COLUMN {column} {definition}")
    for statement, table, columns in INDEXES:
        names = {row[1] for row in connection.execute(f"PRAGMA table_info({table})")}
        if set(columns) <= names:
            connection.execute(statement)
